object GradeMateColors {
    val Primary = Color.rgb(25, 118, 210)
    val PrimaryDark = Color.rgb(17, 82, 147)
    val Secondary = Color.rgb(102, 187, 106)
    val Background = Color.rgb(245, 245, 245)
    val Surface = Color.rgb(255, 255, 255)
    val TextPrimary = Color.rgb(28, 30, 33)
    val TextSecondary = Color.rgb(92, 101, 112)
    val Border = Color.rgb(225, 228, 232)

    const val Primary25 = "rgba(25, 118, 210, 0.25)"
    const val Border35 = "rgba(225, 228, 232, 0.35)"
    val FooterBackground = Color.rgb(15, 27, 45)
    val TextOnDark = Color.rgb(232, 236, 242)
    val TextOnDarkSecondary = Color.rgb(139, 152, 172)
