}
// Top level property
// Top of file, alongside other top-level declarations
val WobbleKeyframes = Keyframes {
    from { Modifier.rotate((-5).deg) }
    to { Modifier.rotate(5.deg) }
}


val HighlightTileGridStyle = CssStyle {
    base {
        Modifier
            .fillMaxWidth()
            .styleModifier {
                property("display", "grid")
                // Single column on phones
                property("grid-template-columns", "1fr")
                property("gap", "14px")
            }
    }
    Breakpoint.SM {
        Modifier.styleModifier {
            // Two columns on small tablets
            property("grid-template-columns", "repeat(2, minmax(0, 1fr))")
