private const val Ease = "cubic-bezier(0.22, 1, 0.36, 1)"
private const val EaseOutBack = "cubic-bezier(0.34, 1.56, 0.64, 1)"

private fun prefersReducedMotion() = window.matchMedia("(prefers-reduced-motion: reduce)").matches

private fun encodeURIComponent(str: String): String =
    js("encodeURIComponent(str)") as String

@Composable
private fun Reveal(
    id: String,
    modifier: Modifier = Modifier,
    delayMs: Int = 0,
    content: @Composable () -> Unit
) {
    var visible by remember { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }

    DisposableEffect(Unit) {
        val check = {
            val top = document.getElementById(id)?.getBoundingClientRect()?.top
            if (reduce || (top != null && top < window.innerHeight * 0.9)) visible = true
        }
        val onScroll: (Event) -> Unit = { check() }
        window.addEventListener("scroll", onScroll)
        check()
        onDispose { window.removeEventListener("scroll", onScroll) }
    }

    Box(
        modifier
            .id(id)
            .fillMaxWidth()
            .styleModifier {
                val d = if (reduce) 0 else delayMs
                val dur = if (reduce) 0 else 900
                property("opacity", if (visible) "1" else "0")
                property("transform", if (visible) "translateY(0)" else "translateY(32px)")
                property(
                    "transition",
                    "opacity ${dur}ms ease ${d}ms, transform ${dur}ms $Ease ${d}ms"
                )
            }
    ) {
        content()
    }
}

