@Composable
fun ContactSection() {
    var name by remember { mutableStateOf("") }
    var email by remember { mutableStateOf("") }
    var message by remember { mutableStateOf("") }
    var statusMessage by remember { mutableStateOf<String?>(null) }
    var statusIsError by remember { mutableStateOf(false) }
    var sendHovered by remember { mutableStateOf(false) }
    var sendPressed by remember { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }
    fun t(ms: Int) = if (reduce) 0 else ms

    Box(
        SectionStyle
            .toModifier()
            .id("contact")
            .backgroundColor(GradeMateColors.Surface)
            .styleModifier {
                // Layered aurora — three soft pools of brand colour
                property(
                    "background-image",
                    "radial-gradient(45% 55% at 88% 78%, ${GradeMateColors.Primary.toRgba(alpha = 0.09f)}, transparent 65%), " +
                            "radial-gradient(35% 45% at 8% 12%, ${GradeMateColors.Primary.toRgba(alpha = 0.05f)}, transparent 70%), " +
                            "radial-gradient(60% 40% at 50% 100%, ${GradeMateColors.Primary.toRgba(alpha = 0.035f)}, transparent 60%)"
                )
                property("position", "relative")
                property("overflow", "hidden")
            }
    ) {
        Div(
            attrs = ResponsiveRowStyle
                .toModifier()
                .then(SectionInnerStyle.toModifier())
                .styleModifier {
                    property("gap", "clamp(40px, 7vw, 96px)")
                    property("align-items", "center")
                    property("position", "relative")
                    property("z-index", "1")
                }
                .toAttrs()
        ) {

            // -------------------------------------------------------------
            // LEFT — intro + direct links
            // -------------------------------------------------------------
            Reveal("contact-intro") {
                Column(Modifier.fillMaxWidth()) {

                    P(
                        EyebrowStyle
                            .toModifier()
                            .margin(0.px)
                            .styleModifier {
                                property("letter-spacing", "0.16em")
                                property("text-transform", "uppercase")
                                property("font-weight", "700")
                                property("font-size", "12px")
                                property("opacity", "0.72")
                            }
                            .toAttrs()
                    ) {
                        Text("Contact us")
                    }

                    P(
                        SectionHeadingStyle
                            .toModifier()
                            .margin(top = 14.px, bottom = 18.px)
                            .styleModifier {
                                property("font-size", "clamp(32px, 4.5vw, 50px)")
                                property("letter-spacing", "-0.04em")
                                property("line-height", "1.05")
                                property("font-weight", "750")
                            }
                            .toAttrs()
                    ) {
                        Text("Questions or feedback?")
                    }

                    P(
                        SectionSubtitleStyle
                            .toModifier()
                            .margin(0.px)
                            .styleModifier {
                                property("line-height", "1.75")
                                property("font-size", "15px")
                                property("max-width", "420px")
                                property("opacity", "0.78")
                            }
                            .toAttrs()
                    ) {
                        Text(
                            "Send a message and we'll get back to you within " +
                                    "a day — or reach out directly."
                        )
                    }

                    Column(
                        Modifier
                            .margin(top = 40.px)
                            .gap(16.px)
                    ) {
                        ContactLink(
                            href = "mailto:lennycodes2000@gmail.com",
                            iconName = "envelope",
                            iconCategory = IconCategory.SOLID,
                            label = "lennycodes2000@gmail.com",
                            sublabel = "Email"
                        )

                        ContactLink(
                            href = "https://wa.me/255686777093",
                            iconName = "whatsapp",
                            iconCategory = IconCategory.BRAND,
                            label = "+255 686 777 093",
                            sublabel = "WhatsApp"
                        )
                    }
                }
            }

            // -------------------------------------------------------------
            // RIGHT — the form
            // -------------------------------------------------------------
            Reveal("contact-form", delayMs = 150) {
                Column(
                    CardStyle
                        .toModifier()
                        .fillMaxWidth()
                        .gap(20.px)
                        .styleModifier {
                            property("padding", "clamp(26px, 4vw, 40px)")
                            property("border-radius", "24px")
                            property(
                                "background-image",
                                "linear-gradient(155deg, rgba(255,255,255,1) 0%, rgba(250,251,253,0.98) 100%)"
                            )
                            property(
                                "box-shadow",
                                "0 40px 80px -48px rgba(15, 23, 42, 0.35), " +
                                        "0 2px 8px -4px rgba(15, 23, 42, 0.06), " +
