                                .margin(0.px)
                                .fontSize(18.px)
                                .fontWeight(FontWeight.Bold)
                                .color(GradeMateColors.TextPrimary)
                                .styleModifier {
                                    property("letter-spacing", "-0.02em")
                                    property("line-height", "1.2")
                                }
