                                // Lift and glow on hover
                                val lift = when {
                                    sendPressed && sendHovered -> "translateY(-1px)"
                                    sendHovered -> "translateY(-3px)"
                                    else -> "translateY(0)"
                                }
                                property("transform", lift)

                                property(
                                    "box-shadow",
                                    when {
                                        sendPressed && sendHovered ->
                                            "0 12px 26px -10px rgba(37, 99, 235, 0.45), " +
                                                    "inset 0 1px 0 rgba(255, 255, 255, 0.2)"
                                        sendHovered ->
                                            "0 22px 40px -12px rgba(37, 99, 235, 0.55), " +
                                                    "inset 0 1px 0 rgba(255, 255, 255, 0.25)"
                                        else ->
                                            "0 10px 24px -10px rgba(37, 99, 235, 0.42), " +
                                                    "inset 0 1px 0 rgba(255, 255, 255, 0.18)"
                                    }
                                )

                                property(
                                    "transition",
                                    "transform ${t(220)}ms $Ease, box-shadow ${t(220)}ms ease"
                                )
                                property("margin-top", "8px")
                            }
                    ) {
                        FaIcon(
                            name = "paper-plane",
                            style = IconCategory.SOLID,
                            modifier = Modifier
                                .fontSize(14.px)
                                .styleModifier {
                                    property(
                                        "transform",
                                        if (sendHovered) "translate(4px, -4px) rotate(-6deg)"
                                        else "translate(0, 0) rotate(0deg)"
                                    )
                                    property(
                                        "transition",
                                        "transform ${t(300)}ms $EaseOutBack"
                                    )
                                }
                        )
                        Text("Send message")
                    }

                    statusMessage?.let { text ->
                        StatusBanner(
                            message = text,
                            isError = statusIsError,
                            onDismiss = { statusMessage = null }
                        )
                    }
                }
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Status banner
// ---------------------------------------------------------------------------
@Composable
private fun StatusBanner(
    message: String,
    isError: Boolean,
    onDismiss: () -> Unit
) {
    var shown by remember(message) { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }

    LaunchedEffect(message) {
        delay(20)
        shown = true
        delay(6000)
        onDismiss()
    }

    val tone = if (isError) "220, 38, 38" else "22, 163, 74"
    val ink = if (isError) "rgb(185, 28, 28)" else "rgb(21, 128, 61)"
    val icon = if (isError) "circle-exclamation" else "circle-check"

    Div(
        attrs = Modifier
            .styleModifier {
                property("display", "flex")
                property("align-items", "flex-start")
                property("gap", "12px")
                property("padding", "14px 18px")
                property("border-radius", "14px")
                property("background-color", "rgba($tone, 0.07)")
                property("border", "1px solid rgba($tone, 0.22)")
                property("color", ink)
                property("font-size", "14px")
                property("font-weight", "500")
                property("line-height", "1.55")
                property("opacity", if (shown) "1" else "0")
                property("transform", if (shown) "translateY(0)" else "translateY(10px)")
                property(
                    "transition",
                    "opacity ${if (reduce) 0 else 400}ms ease, " +
                            "transform ${if (reduce) 0 else 500}ms $Ease"
                )
            }
            .toAttrs { attr("role", if (isError) "alert" else "status") }
    ) {
        FaIcon(
            name = icon,
            style = IconCategory.SOLID,
            modifier = Modifier.fontSize(15.px).styleModifier { property("flex-shrink", "0") }
        )
        Text(message)
    }
}

// ---------------------------------------------------------------------------
// Direct contact link — bigger, richer, with sublabel and animated arrow
// ---------------------------------------------------------------------------
@Composable
private fun ContactLink(
    href: String,
    iconName: String,
    iconCategory: IconCategory,
    label: String,
    sublabel: String,
) {
    var hovered by remember { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }
    fun t(ms: Int) = if (reduce) 0 else ms

    Link(
        href,
        modifier = Modifier
            .fillMaxWidth()
            .onMouseEnter { hovered = true }
            .onMouseLeave { hovered = false }
            .styleModifier {
                property("display", "flex")
                property("align-items", "center")
                property("gap", "16px")
                property("padding", "14px 16px")
                property("border-radius", "16px")
                property("text-decoration", "none")
                property("background-color",
                    if (hovered) GradeMateColors.Primary.toRgba(alpha = 0.045f)
                    else "transparent"
                )
                property("transform", if (hovered) "translateX(4px)" else "translateX(0)")
                property(
                    "transition",
                    "transform ${t(300)}ms $Ease, background-color ${t(250)}ms ease"
                )
            }
    ) {
        // Circular icon chip
        Box(
            Modifier
                .size(46.px)
                .styleModifier {
                    property("display", "inline-flex")
                    property("align-items", "center")
                    property("justify-content", "center")
                    property("border-radius", "999px")
                    property(
                        "background-color",
                        if (hovered) GradeMateColors.Primary.toRgba()
                        else GradeMateColors.Primary.toRgba(alpha = 0.10f)
                    )
                    property(
                        "color",
                        if (hovered) "#ffffff" else GradeMateColors.Primary.toRgba()
                    )
                    property("flex-shrink", "0")
                    property(
                        "box-shadow",
                        if (hovered)
                            "0 14px 26px -10px ${GradeMateColors.Primary.toRgba(alpha = 0.55f)}"
                        else "none"
                    )
                    property(
                        "transform",
                        if (hovered) "scale(1.05)" else "scale(1)"
                    )
                    property(
                        "transition",
                        "background-color ${t(250)}ms ease, " +
                                "color ${t(250)}ms ease, " +
                                "box-shadow ${t(250)}ms ease, " +
                                "transform ${t(350)}ms $EaseOutBack"
                    )
                }
        ) {
            FaIcon(
                name = iconName,
                style = iconCategory,
                modifier = Modifier.fontSize(17.px)
            )
        }

        // Label + sublabel
        Column(Modifier.gap(2.px)) {
            P(
                Modifier
                    .margin(0.px)
                    .fontSize(11.px)
                    .fontWeight(FontWeight.SemiBold)
                    .color(GradeMateColors.TextSecondary)
                    .styleModifier {
                        property("letter-spacing", "0.1em")
                        property("text-transform", "uppercase")
                        property("line-height", "1")
                        property("opacity", "0.7")
                    }
                    .toAttrs()
            ) {
                Text(sublabel)
            }
            P(
                Modifier
                    .margin(0.px)
                    .fontSize(15.px)
                    .fontWeight(FontWeight.SemiBold)
                    .color(GradeMateColors.TextPrimary)
                    .styleModifier {
                        property("letter-spacing", "-0.01em")
                        property("line-height", "1.2")
                    }
                    .toAttrs()
            ) {
                Text(label)
            }
        }

        // Animated arrow
        Div(
            attrs = Modifier
                .styleModifier {
                    property("margin-left", "auto")
                    property("display", "flex")
                    property("align-items", "center")
                    property("justify-content", "center")
                    property("width", "28px")
                    property("height", "28px")
                    property("border-radius", "999px")
                    property(
                        "background-color",
                        if (hovered) GradeMateColors.Primary.toRgba(alpha = 0.12f)
                        else "transparent"
                    )
                    property("color", GradeMateColors.Primary.toRgba())
                    property("opacity", if (hovered) "1" else "0")
                    property(
                        "transform",
                        if (hovered) "translateX(0) scale(1)" else "translateX(-8px) scale(0.9)"
                    )
                    property(
                        "transition",
                        "opacity ${t(220)}ms ease, " +
                                "transform ${t(320)}ms $EaseOutBack, " +
                                "background-color ${t(250)}ms ease"
                    )
                }
                .toAttrs()
        ) {
            FaIcon(
                name = "arrow-right",
                style = IconCategory.SOLID,
                modifier = Modifier.fontSize(11.px)
            )
        }
    }
}

