// ---------------------------------------------------------------------------
// Quick-jump pill — uses A() so the whole pill is clickable and can hold
// both the label and the animated arrow.
// ---------------------------------------------------------------------------
@Composable
private fun DocsPill(text: String, href: String) {
    var hovered by remember { mutableStateOf(false) }
    val reduce = remember { prefersReducedMotion() }
    fun t(ms: Int): Int = if (reduce) 0 else ms

    A(
        href = href,
        attrs = Modifier
            .onMouseEnter { hovered = true }
            .onMouseLeave { hovered = false }
            .styleModifier {
                property("display", "inline-flex")
                property("align-items", "center")
                property("gap", "8px")
                property("padding", "9px 16px 9px 18px")
                property("border-radius", "999px")
                property("text-decoration", "none")
                property("font-size", "13px")
                property("font-weight", "600")
                property("letter-spacing", "-0.005em")
                property(
                    "color",
                    if (hovered) "#ffffff" else GradeMateColors.TextSecondary.toRgba()
                )
                property(
                    "background-color",
                    if (hovered) GradeMateColors.Primary.toString()
                    else GradeMateColors.Background.toRgba()
                )
                property(
                    "border",
                    "1px solid ${
                        if (hovered) GradeMateColors.Primary.toRgba()
                        else GradeMateColors.Border.toRgba()
                    }"
                )
                property(
                    "box-shadow",
                    if (hovered) "0 12px 22px -10px ${GradeMateColors.Primary.toRgba(alpha = 0.5f)}"
                    else "none"
                )
                property("transform", if (hovered) "translateY(-2px)" else "translateY(0)")
                property(
                    "transition",
                    "transform ${t(250)}ms $Ease, " +
                            "background-color ${t(220)}ms ease, " +
                            "border-color ${t(220)}ms ease, " +
                            "color ${t(220)}ms ease, " +
                            "box-shadow ${t(250)}ms ease"
                )
            }
            .toAttrs()
    ) {
        Text(text)

        Span(
            Modifier
                .styleModifier {
                    property("display", "inline-flex")
                    property("align-items", "center")
                    property("justify-content", "center")
                    property("width", "14px")
                    property("height", "14px")
                    property("opacity", if (hovered) "1" else "0")
                    property(
                        "transform",
                        if (hovered) "translateX(0)" else "translateX(-6px)"
                    )
                    property(
                        "transition",
                        "opacity ${t(200)}ms ease, transform ${t(250)}ms $Ease"
                    )
                }.toAttrs()
        ) {
            FaIcon(
                name = "arrow-right",
                style = IconCategory.SOLID,
                modifier = Modifier.fontSize(9.px)
            )
        }
    }
}

